-- 将 V3 下载页的现有条目迁入目录，重复执行保留后台编辑。非默认前缀请替换 symphony_。
CREATE TABLE IF NOT EXISTS `symphony_client_download` (
 `oId` VARCHAR(48) NOT NULL,
 `configJson` TEXT NOT NULL,
 `sortOrder` INT NOT NULL,
 `revision` INT NOT NULL,
 PRIMARY KEY (`oId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

